#include <vector>
#include <algorithm>

class Solution {
public:
    int maxProfit(int n, std::vector<int>& present, std::vector<int>& future, std::vector<std::vector<int>>& hierarchy, int budget) {
        std::vector<std::vector<int>> tree(n);
        for (const auto& edge : hierarchy) {
            tree[edge[0] - 1].push_back(edge[1] - 1);
        }

        auto dfs = [&](auto& self, int u) -> std::pair<std::vector<int>, std::vector<int>> {
            std::vector<int> no_disc(budget + 1, 0);
            std::vector<int> with_disc(budget + 1, 0);

            for (int v : tree[u]) {
                auto [c_no, c_with] = self(self, v);
                std::vector<int> new_no(budget + 1, 0);
                std::vector<int> new_with(budget + 1, 0);
                for (int b1 = 0; b1 <= budget; ++b1) {
                    for (int b2 = 0; b1 + b2 <= budget; ++b2) {
                        new_no[b1 + b2] = std::max(new_no[b1 + b2], no_disc[b1] + c_no[b2]);
                        new_with[b1 + b2] = std::max(new_with[b1 + b2], with_disc[b1] + c_with[b2]);
                    }
                }
                no_disc = std::move(new_no);
                with_disc = std::move(new_with);
            }

            std::vector<int> res0 = no_disc;
            std::vector<int> res1 = no_disc;

            int fc = present[u];
            int fp = future[u] - fc;
            for (int b = fc; b <= budget; ++b) {
                res0[b] = std::max(res0[b], with_disc[b - fc] + fp);
            }

            int hc = present[u] / 2;
            int hp = future[u] - hc;
            for (int b = hc; b <= budget; ++b) {
                res1[b] = std::max(res1[b], with_disc[b - hc] + hp);
            }

            return {res0, res1};
        };

        auto [r0, r1] = dfs(dfs, 0);
        int ans = 0;
        for (int val : r0) ans = std::max(ans, val);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxProfit(int n, int[] present, int[] future, int[][] hierarchy, int budget) {
        List<Integer>[] tree = new ArrayList[n];
        for (int i = 0; i < n; ++i) tree[i] = new ArrayList<>();
        for (int[] edge : hierarchy) {
            tree[edge[0] - 1].add(edge[1] - 1);
        }

        int[][] res = dfs(0, tree, present, future, budget);
        int ans = 0;
        for (int val : res[0]) ans = Math.max(ans, val);
        return ans;
    }

    private int[][] dfs(int u, List<Integer>[] tree, int[] present, int[] future, int budget) {
        int[] noDisc = new int[budget + 1];
        int[] withDisc = new int[budget + 1];

        for (int v : tree[u]) {
            int[][] childRes = dfs(v, tree, present, future, budget);
            int[] cNo = childRes[0];
            int[] cWith = childRes[1];

            int[] newNo = new int[budget + 1];
            int[] newWith = new int[budget + 1];

            for (int b1 = 0; b1 <= budget; ++b1) {
                for (int b2 = 0; b1 + b2 <= budget; ++b2) {
                    newNo[b1 + b2] = Math.max(newNo[b1 + b2], noDisc[b1] + cNo[b2]);
                    newWith[b1 + b2] = Math.max(newWith[b1 + b2], withDisc[b1] + cWith[b2]);
                }
            }
            noDisc = newNo;
            withDisc = newWith;
        }

        int[] res0 = Arrays.copyOf(noDisc, budget + 1);
        int[] res1 = Arrays.copyOf(noDisc, budget + 1);

        int fc = present[u];
        int fp = future[u] - fc;
        for (int b = fc; b <= budget; ++b) {
            res0[b] = Math.max(res0[b], withDisc[b - fc] + fp);
        }

        int hc = present[u] / 2;
        int hp = future[u] - hc;
        for (int b = hc; b <= budget; ++b) {
            res1[b] = Math.max(res1[b], withDisc[b - hc] + hp);
        }

        return new int[][]{res0, res1};
    }
}

/**
 * @param {number} n
 * @param {number[]} present
 * @param {number[]} future
 * @param {number[][]} hierarchy
 * @param {number} budget
 * @return {number}
 */
var maxProfit = function(n, present, future, hierarchy, budget) {
    const tree = Array.from({ length: n }, () => []);
    for (const [u, v] of hierarchy) {
        tree[u - 1].push(v - 1);
    }

    function dfs(u) {
        let noDisc = new Array(budget + 1).fill(0);
        let withDisc = new Array(budget + 1).fill(0);

        for (const v of tree[u]) {
            const [cNo, cWith] = dfs(v);
            const newNo = new Array(budget + 1).fill(0);
            const newWith = new Array(budget + 1).fill(0);

            for (let b1 = 0; b1 <= budget; ++b1) {
                for (let b2 = 0; b1 + b2 <= budget; ++b2) {
                    newNo[b1 + b2] = Math.max(newNo[b1 + b2], noDisc[b1] + cNo[b2]);
                    newWith[b1 + b2] = Math.max(newWith[b1 + b2], withDisc[b1] + cWith[b2]);
                }
            }
            noDisc = newNo;
            withDisc = newWith;
        }

        const res0 = [...noDisc];
        const res1 = [...noDisc];

        const fc = present[u];
        const fp = future[u] - fc;
        for (let b = fc; b <= budget; ++b) {
            res0[b] = Math.max(res0[b], withDisc[b - fc] + fp);
        }

        const hc = Math.floor(present[u] / 2);
        const hp = future[u] - hc;
        for (let b = hc; b <= budget; ++b) {
            res1[b] = Math.max(res1[b], withDisc[b - hc] + hp);
        }

        return [res0, res1];
    }

    const [r0] = dfs(0);
    return Math.max(...r0);
};
